// Builds the "AI ends chat" short as an editable After Effects project (AE 2022+).
// File > Scripts > Run Script File... and pick this file. Keep the folder structure
// next to it (audio/, out/, emoji/) so the footage can be imported.
// Generated by ae/build.mjs from the same timeline as the web version.
(function () {
  var D = __DATA__;
  var ROOT = File($.fileName).parent;
  var WARN = [];

  function rgb(h) {
    h = String(h).replace('#', '');
    return [parseInt(h.substr(0, 2), 16) / 255, parseInt(h.substr(2, 2), 16) / 255, parseInt(h.substr(4, 2), 16) / 255];
  }
  function isArr(v) { return v != null && typeof v === 'object' && typeof v.length === 'number'; }

  // ---------------------------------------------------------------- shapes
  function contents(g) { return g.property('ADBE Vectors Group') || g.property('ADBE Root Vectors Group'); }
  function styleShape(c, p) {
    if (p.fill) {
      var f = c.addProperty('ADBE Vector Graphic - Fill');
      f.property('ADBE Vector Fill Color').setValue(rgb(p.fill));
      if (p.op != null) f.property('ADBE Vector Fill Opacity').setValue(p.op);
    }
    if (p.stroke) {
      var s = c.addProperty('ADBE Vector Graphic - Stroke');
      s.property('ADBE Vector Stroke Color').setValue(rgb(p.stroke));
      s.property('ADBE Vector Stroke Width').setValue(p.sw || 1);
      if (p.sop != null) s.property('ADBE Vector Stroke Opacity').setValue(p.sop);
      if (p.cap === 'round') {
        try { s.property('ADBE Vector Stroke Line Cap').setValue(2); s.property('ADBE Vector Stroke Line Join').setValue(2); } catch (e) {}
      }
    }
  }
  function addPrims(c, prims) {
    for (var i = 0; i < prims.length; i++) {
      var p = prims[i];
      if (p.t === 'group') {
        var g = c.addProperty('ADBE Vector Group');
        if (p.name) g.name = p.name;
        addPrims(contents(g), p.kids);
        var tf = g.property('ADBE Vector Transform Group');
        tf.property('ADBE Vector Position').setValue([p.x || 0, p.y || 0]);
        if (p.rot) tf.property('ADBE Vector Rotation').setValue(p.rot);
        if (p.sc != null && p.sc !== 100) tf.property('ADBE Vector Scale').setValue([p.sc, p.sc]);
        if (p.op != null && p.op !== 100) tf.property('ADBE Vector Group Opacity').setValue(p.op);
      } else if (p.t === 'rep') {
        var r = c.addProperty('ADBE Vector Filter - Repeater');
        r.property('ADBE Vector Repeater Copies').setValue(p.copies);
        r.property('ADBE Vector Repeater Transform').property('ADBE Vector Repeater Position').setValue([p.dx, p.dy]);
      } else if (p.t === 'trim') {
        var tr = c.addProperty('ADBE Vector Filter - Trim');
        tr.property('ADBE Vector Trim Start').setValue(p.start);
        tr.property('ADBE Vector Trim End').setValue(p.end);
      } else if (p.t === 'text') {
        // handled as separate layers
      } else {
        // every primitive sits in its own group so fill/stroke stay local
        var gg = c.addProperty('ADBE Vector Group');
        if (p.name) gg.name = p.name;
        var cc = contents(gg);
        if (p.t === 'rect') {
          var rc = cc.addProperty('ADBE Vector Shape - Rect');
          rc.property('ADBE Vector Rect Size').setValue([p.w, p.h]);
          rc.property('ADBE Vector Rect Position').setValue([p.x + p.w / 2, p.y + p.h / 2]);
          rc.property('ADBE Vector Rect Roundness').setValue(Math.min(p.r || 0, p.w / 2, p.h / 2));
        } else if (p.t === 'ell') {
          var el = cc.addProperty('ADBE Vector Shape - Ellipse');
          el.property('ADBE Vector Ellipse Size').setValue([p.rx * 2, p.ry * 2]);
          el.property('ADBE Vector Ellipse Position').setValue([p.cx, p.cy]);
        } else if (p.t === 'path') {
          var ph = cc.addProperty('ADBE Vector Shape - Group');
          var sh = new Shape();
          sh.vertices = p.v; sh.inTangents = p.i; sh.outTangents = p.o; sh.closed = !!p.closed;
          ph.property('ADBE Vector Shape').setValue(sh);
        }
        styleShape(cc, p);
      }
    }
  }
  function findGroup(c, name) {
    for (var i = 1; i <= c.numProperties; i++) {
      var p = c.property(i);
      if (p.matchName === 'ADBE Vector Group') {
        if (p.name === name) return p;
        var r = findGroup(contents(p), name);
        if (r) return r;
      }
    }
    return null;
  }
  function findIn(g, matchName) {
    var c = contents(g);
    for (var i = 1; i <= c.numProperties; i++) {
      var p = c.property(i);
      if (p.matchName === matchName) return p;
      if (p.matchName === 'ADBE Vector Group') { var r = findIn(p, matchName); if (r) return r; }
    }
    return null;
  }

  // ---------------------------------------------------------------- keys
  function dims(prop) {
    var t = prop.propertyValueType;
    if (t === PropertyValueType.ThreeD_SPATIAL || t === PropertyValueType.TwoD_SPATIAL) return 1;
    if (t === PropertyValueType.ThreeD) return 3;
    if (t === PropertyValueType.TwoD) return 2;
    return 1;
  }
  function fit(prop, v) {
    if (prop.propertyValueType === PropertyValueType.COLOR && typeof v === 'string') { var c = rgb(v); c.push(1); return c; }
    if (!isArr(v) && isArr(prop.value) && prop.value.length >= 2 && prop.propertyValueType !== PropertyValueType.COLOR) {
      var a = []; for (var i = 0; i < prop.value.length; i++) a.push(i < 2 ? v : 100); return a;
    }
    if (isArr(v) && isArr(prop.value) && prop.value.length === 3 && v.length === 2) {
      return [v[0], v[1], prop.matchName === 'ADBE Scale' ? 100 : 0];
    }
    return v;
  }
  function ease(prop, idx, inf) {
    var tries = [dims(prop), 1, 2, 3, 4];
    for (var t = 0; t < tries.length; t++) {
      try {
        var a = [], b = [];
        for (var j = 0; j < tries[t]; j++) { a.push(new KeyframeEase(0, Math.max(0.1, inf[0] || 33))); b.push(new KeyframeEase(0, Math.max(0.1, inf[1] || 33))); }
        prop.setTemporalEaseAtKey(idx, a, b);
        return;
      } catch (e) {}
    }
  }
  // key: [time, value, inInfluence|null(linear), outInfluence|null(linear), hold]
  function setKeys(prop, keys) {
    if (!prop || !keys || !keys.length) return;
    var i, k, idx;
    for (i = 0; i < keys.length; i++) prop.setValueAtTime(keys[i][0], fit(prop, keys[i][1]));
    var spatial = prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL || prop.propertyValueType === PropertyValueType.TwoD_SPATIAL;
    for (i = 0; i < keys.length; i++) {
      k = keys[i]; idx = prop.nearestKeyIndex(k[0]);
      try {
        if (k[4]) { prop.setInterpolationTypeAtKey(idx, KeyframeInterpolationType.HOLD, KeyframeInterpolationType.HOLD); continue; }
        if (k[2] != null || k[3] != null) ease(prop, idx, [k[2] == null ? 33 : k[2], k[3] == null ? 33 : k[3]]);
        prop.setInterpolationTypeAtKey(idx,
          k[2] == null ? KeyframeInterpolationType.LINEAR : KeyframeInterpolationType.BEZIER,
          k[3] == null ? KeyframeInterpolationType.LINEAR : KeyframeInterpolationType.BEZIER);
        if (spatial) {
          var z = []; for (var d = 0; d < prop.value.length; d++) z.push(0);
          prop.setSpatialTangentsAtKey(idx, z, z);
        }
      } catch (e) {}
    }
  }
  var TP = { pos: 'ADBE Position', scale: 'ADBE Scale', rot: 'ADBE Rotate Z', op: 'ADBE Opacity', anchor: 'ADBE Anchor Point' };
  var GP = { pos: 'ADBE Vector Position', scale: 'ADBE Vector Scale', rot: 'ADBE Vector Rotation', op: 'ADBE Vector Group Opacity', anchor: 'ADBE Vector Anchor' };

  // ---------------------------------------------------------------- text
  function textDoc(layer, o, doc) {
    var d = doc || layer.property('ADBE Text Properties').property('ADBE Text Document').value;
    try { d.resetCharStyle(); d.resetParagraphStyle(); } catch (e) {}
    d.text = o.text;
    try { d.font = o.font; } catch (e1) { WARN.push('font ' + o.font); }
    d.fontSize = o.size;
    d.applyFill = true;
    d.fillColor = rgb(o.fill || '#FFFFFF');
    if (o.stroke) { d.applyStroke = true; d.strokeColor = rgb(o.stroke); d.strokeWidth = o.sw; d.strokeOverFill = false; }
    else d.applyStroke = false;
    d.justification = o.just === 'center' ? ParagraphJustification.CENTER_JUSTIFY : o.just === 'right' ? ParagraphJustification.RIGHT_JUSTIFY : ParagraphJustification.LEFT_JUSTIFY;
    d.tracking = o.tracking || 0;
    if (o.leading) { d.autoLeading = false; d.leading = o.leading; }
    return d;
  }
  function highlight(layer, hl) {
    // fill-colour animator whose amount is keyed per word; falls back to a duplicate layer
    var an = null;
    try {
      var anims = layer.property('ADBE Text Properties').property('ADBE Text Animators');
      an = anims.addProperty('ADBE Text Animator');
      an.name = 'Highlight';
      var fc = an.property('ADBE Text Animator Properties').addProperty('ADBE Text Fill Color');
      fc.setValue(rgb(hl.color));
      var sel = an.property('ADBE Text Selectors').addProperty('ADBE Text Selector');
      var amt = sel.property('ADBE Text Range Advanced').property('ADBE Text Selector Max Amount');
      setKeys(amt, hl.keys);
      return null;
    } catch (e) {
      try { if (an) an.remove(); } catch (e3) {}
      var dup = layer.duplicate();
      dup.name = layer.name + ' (highlight)';
      var tp = dup.property('ADBE Text Properties').property('ADBE Text Document');
      var d = tp.value; d.fillColor = rgb(hl.color); tp.setValue(d);
      dup.moveBefore(layer);
      setKeys(dup.property('ADBE Opacity'), hl.keys);
      return dup;
    }
  }
  function reveal(layer, rv) {
    var an = null;
    try {
      an = layer.property('ADBE Text Properties').property('ADBE Text Animators').addProperty('ADBE Text Animator');
      an.name = 'Reveal';
      var props = an.property('ADBE Text Animator Properties');
      props.addProperty('ADBE Text Position 3D').setValue([0, rv.dy, 0]);
      props.addProperty('ADBE Text Opacity').setValue(0);
      props.addProperty('ADBE Text Rotation').setValue(rv.rot || 0);
      var sel = an.property('ADBE Text Selectors').addProperty('ADBE Text Selector');
      var adv = sel.property('ADBE Text Range Advanced');
      try { adv.property('ADBE Text Range Shape').setValue(2); } catch (e2) {} // ramp up
      setKeys(sel.property('ADBE Text Percent Start'), rv.keys);
    } catch (e) {
      try { if (an) an.remove(); } catch (e3) {}
      setKeys(layer.property('ADBE Opacity'), [[rv.keys[0][0], 0, null, null], [rv.keys[rv.keys.length - 1][0], 100, null, null]]);
    }
  }

  // ---------------------------------------------------------------- effects & masks
  function addEffects(layer, list) {
    for (var i = 0; i < list.length; i++) {
      var ef = list[i];
      try {
        var e = layer.property('ADBE Effect Parade').addProperty(ef.m);
        if (ef.name) e.name = ef.name;
        for (var k in ef.p) if (ef.p.hasOwnProperty(k)) {
          var pr = e.property(parseInt(k, 10));
          var v = ef.p[k];
          if (typeof v === 'string') { v = rgb(v); v.push(1); }
          try { pr.setValue(v); }
          catch (e1) {
            // some legacy effects take 0..255 or 0..100 depending on the version
            try { pr.setValue(typeof v === 'number' && v > 100 ? v / 2.55 : v); } catch (e2) { WARN.push(layer.name + ': ' + ef.m + ' #' + k); }
          }
        }
        if (ef.k) for (var kk in ef.k) if (ef.k.hasOwnProperty(kk)) setKeys(e.property(parseInt(kk, 10)), ef.k[kk]);
        if (ef.x) for (var kx in ef.x) if (ef.x.hasOwnProperty(kx)) e.property(parseInt(kx, 10)).expression = ef.x[kx];
      } catch (err) { WARN.push(layer.name + ': effect ' + ef.m + ' (' + err + ')'); }
    }
  }
  function ellipseShape(x, y, w, h) {
    var k = 0.5523, rx = w / 2, ry = h / 2, cx = x + rx, cy = y + ry;
    var s = new Shape();
    s.vertices = [[cx, y], [x + w, cy], [cx, y + h], [x, cy]];
    s.inTangents = [[-rx * k, 0], [0, -ry * k], [rx * k, 0], [0, ry * k]];
    s.outTangents = [[rx * k, 0], [0, ry * k], [-rx * k, 0], [0, -ry * k]];
    s.closed = true;
    return s;
  }
  function addMasks(layer, list) {
    for (var i = 0; i < list.length; i++) {
      var m = list[i];
      var mk = layer.property('ADBE Mask Parade').addProperty('ADBE Mask Atom');
      mk.property('ADBE Mask Shape').setValue(ellipseShape(m.x, m.y, m.w, m.h));
      if (m.feather) mk.property('ADBE Mask Feather').setValue([m.feather, m.feather]);
      mk.inverted = !!m.inverted;
    }
  }

  // ---------------------------------------------------------------- build
  if (!app.project) app.newProject();
  var proj = app.project;
  app.beginUndoGroup('Build ' + D.title);

  var FOLDER = proj.items.addFolder(D.title);
  var PRE = proj.items.addFolder('Precomps'); PRE.parentFolder = FOLDER;
  var FOOTF = proj.items.addFolder('Footage'); FOOTF.parentFolder = FOLDER;

  var FOOT = {};
  for (var fi = 0; fi < D.footage.length; fi++) {
    var fd = D.footage[fi];
    var file = new File(ROOT.fsName + '/' + fd.path);
    if (!file.exists) { WARN.push('missing file ' + fd.path); continue; }
    try { FOOT[fd.id] = proj.importFile(new ImportOptions(file)); FOOT[fd.id].parentFolder = FOOTF; }
    catch (e) { WARN.push('import ' + fd.path + ': ' + e); }
  }

  var COMPS = {};
  for (var ci = 0; ci < D.comps.length; ci++) {
    var cd = D.comps[ci];
    var c = proj.items.addComp(cd.name, cd.w, cd.h, 1, cd.dur, D.fps);
    c.bgColor = rgb(cd.bg || '#0E1325');
    c.parentFolder = cd.main ? FOLDER : PRE;
    COMPS[cd.id] = c;
  }

  function buildComp(cd) {
    var comp = COMPS[cd.id];
    var made = [], byName = {};
    // create bottom-up so the stacking order matches the spec (first = top)
    for (var i = cd.layers.length - 1; i >= 0; i--) {
      var s = cd.layers[i], L = null;
      try {
        if (s.type === 'shape') { L = comp.layers.addShape(); addPrims(L.property('ADBE Root Vectors Group'), s.prims || []); }
        else if (s.type === 'text') { L = comp.layers.addText(s.text.text); var tp = L.property('ADBE Text Properties').property('ADBE Text Document'); tp.setValue(textDoc(L, s.text)); }
        else if (s.type === 'null') { L = comp.layers.addNull(); }
        else if (s.type === 'solid') { L = comp.layers.addSolid(rgb(s.color), s.name, s.w || comp.width, s.h || comp.height, 1); }
        else if (s.type === 'adjust') { L = comp.layers.addSolid([1, 1, 1], s.name, comp.width, comp.height, 1); L.adjustmentLayer = true; }
        else if (s.type === 'comp') { L = comp.layers.add(COMPS[s.comp]); }
        else if (s.type === 'footage') { if (!FOOT[s.footage]) continue; L = comp.layers.add(FOOT[s.footage]); }
      } catch (e) { WARN.push(cd.name + ' / ' + s.name + ': ' + e); continue; }
      if (!L) continue;
      L.name = s.name;
      if (s.label) L.label = s.label;
      made.push([s, L]); byName[s.name] = L;
    }
    // parents first, then local transforms
    for (var j = 0; j < made.length; j++) {
      var sp = made[j][0];
      if (sp.parent && byName[sp.parent]) made[j][1].parent = byName[sp.parent];
    }
    for (j = 0; j < made.length; j++) {
      var S = made[j][0], Ly = made[j][1];
      try {
        var tg = Ly.property('ADBE Transform Group');
        if (S.anchor) tg.property('ADBE Anchor Point').setValue(fit(tg.property('ADBE Anchor Point'), S.anchor));
        if (S.pos) tg.property('ADBE Position').setValue(fit(tg.property('ADBE Position'), S.pos));
        if (S.scale != null) tg.property('ADBE Scale').setValue(fit(tg.property('ADBE Scale'), S.scale));
        if (S.rot) tg.property('ADBE Rotate Z').setValue(S.rot);
        if (S.op != null) tg.property('ADBE Opacity').setValue(S.op);
        if (S.keys) for (var kp in S.keys) if (S.keys.hasOwnProperty(kp)) setKeys(tg.property(TP[kp]), S.keys[kp]);
        if (S.expr) for (var ep in S.expr) if (S.expr.hasOwnProperty(ep)) tg.property(TP[ep]).expression = S.expr[ep];
        if (S.gkeys) for (var gn in S.gkeys) if (S.gkeys.hasOwnProperty(gn)) {
          var grp = findGroup(Ly.property('ADBE Root Vectors Group'), gn);
          if (!grp) { WARN.push('no group ' + gn + ' in ' + S.name); continue; }
          var gk = S.gkeys[gn];
          for (var gp in gk) if (gk.hasOwnProperty(gp)) {
            var prop = null;
            if (GP[gp]) prop = grp.property('ADBE Vector Transform Group').property(GP[gp]);
            else if (gp === 'fill') { var fl = findIn(grp, 'ADBE Vector Graphic - Fill'); prop = fl && fl.property('ADBE Vector Fill Color'); }
            else if (gp === 'fillOp') { var fo = findIn(grp, 'ADBE Vector Graphic - Fill'); prop = fo && fo.property('ADBE Vector Fill Opacity'); }
            else if (gp === 'stroke') { var st = findIn(grp, 'ADBE Vector Graphic - Stroke'); prop = st && st.property('ADBE Vector Stroke Color'); }
            else if (gp === 'size') { var es = findIn(grp, 'ADBE Vector Shape - Ellipse'); prop = es && es.property('ADBE Vector Ellipse Size'); }
            else if (gp === 'sw') { var sw = findIn(grp, 'ADBE Vector Graphic - Stroke'); prop = sw && sw.property('ADBE Vector Stroke Width'); }
            else if (gp === 'trimEnd') { var tr = findIn(grp, 'ADBE Vector Filter - Trim'); prop = tr && tr.property('ADBE Vector Trim End'); }
            if (gp.charAt(0) === 'x') { var xp = grp.property('ADBE Vector Transform Group').property(GP[gp.substr(1)]); if (xp) xp.expression = gk[gp]; continue; }
            setKeys(prop, gk[gp]);
          }
        }
        if (S.text && S.text.keys) {
          var tdp = Ly.property('ADBE Text Properties').property('ADBE Text Document');
          for (var tk = 0; tk < S.text.keys.length; tk++) {
            var o = {}; for (var q in S.text) if (S.text.hasOwnProperty(q)) o[q] = S.text[q];
            o.text = S.text.keys[tk][1];
            tdp.setValueAtTime(S.text.keys[tk][0], textDoc(Ly, o, tdp.value));
          }
        }
        if (S.hl) highlight(Ly, S.hl);
        if (S.reveal) reveal(Ly, S.reveal);
        if (S.effects) addEffects(Ly, S.effects);
        if (S.masks) addMasks(Ly, S.masks);
        if (S.blend) Ly.blendingMode = S.blend === 'screen' ? BlendingMode.SCREEN : S.blend === 'add' ? BlendingMode.ADD : BlendingMode.NORMAL;
        if (S.audio != null) { try { Ly.property('ADBE Audio Group').property('ADBE Audio Levels').setValue([S.audio, S.audio]); } catch (ea) {} }
        if (S.out != null) Ly.outPoint = Math.min(S.out, comp.duration);
        if (S['in'] != null) { Ly.inPoint = Math.max(0, S['in']); if (S.out != null) Ly.outPoint = Math.min(S.out, comp.duration); }
        if (S.start != null) Ly.startTime = S.start;
        if (S.guide) Ly.guideLayer = true;
      } catch (err) { WARN.push(cd.name + ' / ' + S.name + ': ' + err); }
    }
    if (cd.markers) for (var mi = 0; mi < cd.markers.length; mi++) {
      try { comp.markerProperty.setValueAtTime(cd.markers[mi][0], new MarkerValue(cd.markers[mi][1])); } catch (em) {}
    }
  }

  for (ci = 0; ci < D.comps.length; ci++) {
    try { buildComp(D.comps[ci]); } catch (e) { WARN.push('comp ' + D.comps[ci].name + ': ' + e); }
  }
  for (ci = 0; ci < D.comps.length; ci++) if (D.comps[ci].main) COMPS[D.comps[ci].id].openInViewer();

  app.endUndoGroup();
  var msg = D.title + ' is built.\n\nSave the project (File > Save As) next to this script.';
  if (WARN.length) msg += '\n\nNotes (' + WARN.length + '):\n' + WARN.slice(0, 25).join('\n');
  alert(msg);
})();
